import React from "react";
import { measureRenders } from "reassure";
import { fireEvent, screen } from "@testing-library/react";
import Delete from "@material-design-icons/svg/filled/delete.svg?react";
import Download from "@material-design-icons/svg/filled/download.svg?react";
import Button from "../Button";
import Flex from "../Flex";
import Stack from "../Stack";
import DataTable, {
  DataTableExpandableOptions,
  DataTableExpandedState,
  DataTableRow,
} from ".";
import mockData, { columns, ExampleRowData, mockNestedData } from "./mockData";

jest.setTimeout(60_000);

describe("DataTable", () => {
  test("Expandable", async () => {
    const data = mockData(1000);
    data[0].nestedData = mockNestedData(2);
    data[1].longDesc = "";

    const ExpandedRow = ({ rowData }: { rowData: ExampleRowData }) => {
      return (
        <Flex
          className="datatable-expandedrow-example"
          alignItems="start"
          justify="space-between"
        >
          <Stack spacing="half-x">
            <label>
              <strong>Long description</strong>
            </label>
            <div>{rowData.longDesc}</div>
            {rowData.nestedData && (
              <>
                <label>
                  <strong>Optional nested data</strong>
                </label>
                <pre>{JSON.stringify(rowData.nestedData)}</pre>
              </>
            )}
          </Stack>
          <Stack align="end">
            <Button variant="ghost" size="small">
              <Download />
              Download
            </Button>
            <Button variant="ghost" size="small">
              <Delete />
              Delete
            </Button>
          </Stack>
        </Flex>
      );
    };

    const getExpandableOptions = (
      expandedRows: DataTableExpandedState,
      renderToggle: boolean
    ): DataTableExpandableOptions<ExampleRowData> => ({
      expandedRows,
      height: 82,
      getRowHeight: (row: DataTableRow<ExampleRowData>) =>
        row.original.nestedData && row.original.nestedData.length > 0
          ? 124
          : 82,
      isRowExpandable: (row: DataTableRow<ExampleRowData>) => {
        return !!(row.original.longDesc && row.original.longDesc.length > 0);
      },
      renderExpanded: (row: DataTableRow<ExampleRowData>) => {
        if (renderToggle) {
          return <span>alternative expanded render</span>;
        } else {
          return <ExpandedRow rowData={row.original} />;
        }
      },
    });

    const ExpandableDataTable = () => {
      const [expandedRows, setExpandedRows] =
        React.useState<DataTableExpandedState>({ "0": true, "2": true });
      const [renderToggle, setRenderToggle] = React.useState(false);
      const expandableOptions = React.useMemo(() => {
        const options = getExpandableOptions(expandedRows, renderToggle);
        options.onChange = (rows: DataTableExpandedState) => {
          setExpandedRows(rows);
        };
        return options;
      }, [expandedRows, renderToggle]);
      return (
        <>
          <DataTable
            allowDividers
            columns={columns}
            data={data}
            expandable
            expandableOptions={expandableOptions}
          />
          <Button
            variant="ghost"
            onClick={() => setRenderToggle((prev) => !prev)}
          >
            Toggle render
          </Button>
        </>
      );
    };

    const scenario = async () => {
      const headerExpandButton = screen.getByRole("button", {
        name: "Toggle Row Expanded header",
      });
      const toggleRenderButton = screen.getByRole("button", {
        name: "Toggle render",
      });
      // expand/collapse all rows
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      // check that expanded content is visible
      await screen.findByText("Optional nested data");
      // toggle expandableOptions with alternative render
      fireEvent.click(toggleRenderButton);
      // expand/collapse all rows
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      fireEvent.click(headerExpandButton);
      // check alternative render of expanded rows
      await screen.findAllByText("alternative expanded render");
    };

    await measureRenders(<ExpandableDataTable />, {
      scenario,
    });
  });
});
